void jogo (unsigned char **M, int i, int j) {
unsigned char qtd_viz_vivos = 0;
int p, q;
for (p=-1; p<=1; p++)
for (q=-1; q<=1; q++)
qtd_viz_vivos+= M[i+p][j+q];
qtd_viz_vivos-= M[i][q]; // subtrai a central
if (qtd_viz_vivos<2 || qtd_viz_vivos>3)
M[i][j]=0;
else if (qtd_viz_vivos==3)
M[i][j]=1
}
unsigned char jogo (unsigned char **M, int i, int j) {
unsigned char qtd_viz_vivos = 0;
int p, q;
for (p=i-1; p<=i+1; p++)
for (q=j-1; q<=j+1; q++)
if ( !(p==i && q==j) ) // não soma atual
qtd_viz_vivos+= M[i][j];
if ( (M[i][j] && qtd_viz_vivos<2) ||
(M[i][j] && qtd_viz_vivos>3) )
M[i][j] = 0;
else if( (M[i][j] && qtd_viz_vivos==2) ||
qtd_viz_vivos==3 )
M[i][j] = 1;
return M[i][j]; // Bastaria atualizar M, pois é passada
// como referência, mas como foi declarada
// diferente de void, deve retornar o valor
}
